// Des: Test helper: run a table of job cases on the fake site and check what the fake page recorded
// Flo: set caps + paths > per case: irreversible rows must refuse without --force > run > count > records > typed values
// I/O: Rig + Case rows (tests only) > pass or a named failure on stderr; never writes to stdout
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const task = @import("ru-task-runn.zig"); const jobs = @import("ru-jobs-tabl.zig"); const jrun = @import("ru-jobs-main.zig"); const cfgz = @import("cf-conf-load.zig");
pub const SECR: task.Secr = .{ .login = "u@fb.test", .pass = "pw-test-1", .newp = "pw-test-2", .firs = "Anh", .last = "Tran", .mail = "u@fb.test", .birt = "1990-01-02" };
pub const Case = struct { name: []const u8, args: task.Args = .{}, force: bool = false, recs: []const []const u8 = &.{}, typed: []const []const u8 = &.{}, num: u32 = 1, comp: []const u8 = "", pkey: []const u8 = "", pval: []const u8 = "" };
pub fn prep(rig: *rigz.Rig) void { const big: u32 = 500; rig.conf.base_bizz_main = rig.base(); rig.conf.base_deve_main = rig.base(); rig.conf.wait_maxx_secs = 20; rig.conf.noti_chai_orde = &.{"file"}; rig.conf.capz_post_dayz = big; rig.conf.capz_comm_dayz = big; rig.conf.capz_mark_dayz = big; rig.conf.capz_grou_dayz = big; rig.conf.capz_frie_dayz = big; rig.conf.capz_dmsg_dayz = big; rig.conf.capz_reac_dayz = big; rig.conf.capz_shar_dayz = big; rig.conf.capz_admn_dayz = big; rig.conf.capz_evnt_dayz = big; rig.conf.capz_stor_dayz = big; rig.conf.capz_prof_dayz = big; rig.conf.capz_acct_dayz = big; rig.conf.capz_data_dayz = big; rig.conf.capz_mone_dayz = big; rig.conf.capz_help_dayz = big; rig.conf.mone_spen_capz = 100; }
pub fn hasIn(rig: *rigz.Rig, needle: []const u8) bool { var ix: usize = 0; while (ix < rig.mock.recCnt()) : (ix += 1) { if (std.mem.find(u8, rig.mock.recAt(ix), needle) != null) return true; } return false; }
pub fn waitIn(rig: *rigz.Rig, needle: []const u8, mill: u32) bool { var tries: u32 = 0; while (tries < mill / 50) : (tries += 1) { if (hasIn(rig, needle)) return true; std.Io.sleep(rig.iozz, .fromMilliseconds(50), .awake) catch {}; } return false; }
fn setPath(conf: *cfgz.Conf, name: []const u8, val: []const u8) void { const info = @typeInfo(cfgz.Conf).@"struct"; inline for (info.field_names, info.field_types) |fnm, fty| { if (fty == []const u8 and std.mem.eql(u8, fnm, name)) @field(conf, fnm) = val; } }
pub fn mk(rig: *rigz.Rig, mode: task.Mode, dataroot: []const u8) task.Ctx { var cx = rig.ctx(mode); cx.secr = SECR; cx.dataroot = dataroot; return cx; }
fn refuse(rig: *rigz.Rig, cs: Case, jb: *const jobs.Job, args: task.Args, droot: []const u8) !void { var cx = mk(rig, .live, droot); if (jrun.run(&cx, jb, args)) |_| { std.debug.print("{s}: ran without approval\n", .{cs.name}); return error.TestUnexpectedResult; } else |err| { if (err != error.NeedApprove) { std.debug.print("{s}: expected NeedApprove, got {s}\n", .{ cs.name, @errorName(err) }); return err; } } }
pub fn runAll(rig: *rigz.Rig, cases: []const Case) !void { prep(rig); const pho = try rig.absOf("p.jpg"); try std.Io.Dir.cwd().writeFile(rig.iozz, .{ .sub_path = try std.fmt.allocPrint(rig.aren.allocator(), ".zig-cache/tmp/{s}/p.jpg", .{rig.tmpz.sub_path}), .data = "JPG" }); const droot = try rig.absOf("data");
for (cases) |cs| { var args = cs.args; if (args.photo.len > 0) args.photo = pho; rig.conf.path_post_comp = if (cs.comp.len > 0) cs.comp else "/"; const old = if (cs.pkey.len > 0) cfgz.confPath(rig.conf, cs.pkey) else ""; if (cs.pkey.len > 0) setPath(&rig.conf, cs.pkey, cs.pval); defer if (cs.pkey.len > 0) setPath(&rig.conf, cs.pkey, old); const jb = jobs.find(cs.name) orelse { std.debug.print("no such job: {s}\n", .{cs.name}); return error.TestUnexpectedResult; };
if (cs.force) try refuse(rig, cs, jb, args, droot);
var c2 = mk(rig, if (cs.force) .force else .live, droot); const done = jrun.run(&c2, jb, args) catch |err| { std.debug.print("{s}: failed with {s}\n{s}\n", .{ cs.name, @errorName(err), if (rig.sink.items.len > 300) rig.sink.items[rig.sink.items.len - 300 ..] else rig.sink.items }); return err; }; if (done != cs.num) { std.debug.print("{s}: done {d}, wanted {d}\n", .{ cs.name, done, cs.num }); return error.TestUnexpectedResult; }
for (cs.recs) |rec| { if (!rig.waitPre(rec, 4000)) { std.debug.print("{s}: missing record {s}\n", .{ cs.name, rec }); var dx: usize = if (rig.mock.recCnt() > 12) rig.mock.recCnt() - 12 else 0; while (dx < rig.mock.recCnt()) : (dx += 1) std.debug.print("  rec {s}\n", .{rig.mock.recAt(dx)}); return error.TestUnexpectedResult; } } for (cs.typed) |val| { if (!waitIn(rig, val, 4000)) { std.debug.print("{s}: typed text not seen: {s}\n", .{ cs.name, val }); return error.TestUnexpectedResult; } } } }
pub fn coverage(cases: []const Case, idx: usize) !void { const rows = jobs.AREAS[idx]; try std.testing.expectEqual(rows.len, cases.len); for (rows) |jb| { var seen = false; for (cases) |cs| { if (std.mem.eql(u8, cs.name, jb.name)) seen = true; } if (!seen) { std.debug.print("no case for {s}\n", .{jb.name}); return error.TestUnexpectedResult; } } }
